55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	const CURSE_SURCHARGE_RATE = 0.5;
58	const HIGH_ENCHANTMENT_THRESHOLD = 5;
59	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
60	const LOYALTY_THRESHOLD_YEARS = 2;
61	const LOYALTY_DISCOUNT_RATE = 0.2;
62	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
63	const DEDUCTIBLE_PER_DAMAGE = 100;
64	const CAP_MULTIPLIER = 2;
65	
66	const INSURANCE_VALUES: Record<string, number> = {
67	  sword: 1000,
68	  amulet: 600,
69	  staff: 800,
70	  potion: 400,
71	  rune: 250,
72	  moonstone: 250,
73	};
74	
75	const BASE_PREMIUMS: Record<string, number> = {
76	  sword: 100,
77	  amulet: 60,
78	  staff: 80,
79	  potion: 40,
80	  rune: 25,
81	  moonstone: 25,
82	};
83	
84	const BLOCK_SIZE = 3;
85	const BLOCK_BASE_PREMIUM = 60;
86	
87	const countByType = (items: Item[]): Map<string, number> => {
88	  const counts = new Map<string, number>();
89	  for (const item of items) {
90	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
91	  }
92	  return counts;
93	};
94	
95	const basePremiumOfType = (type: string): number => BASE_PREMIUMS[type];
96	
97	const basePremiumOfAlikeItems = (type: string, count: number): number =>
98	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * basePremiumOfType(type);
99	
100	const policyBasePremium = (items: Item[]): number =>
101	  [...countByType(items)].reduce(
102	    (total, [type, count]) => total + basePremiumOfAlikeItems(type, count),
103	    0,
104	  );
105	
106	const firstInsuranceSurcharge = (policyBase: number): number =>
107	  policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
108	
109	const itemBasePremium = (item: Item): number => basePremiumOfType(item.type);
110	
111	const isCursed = (item: Item): boolean => item.cursed === true;
112	
113	const isHighlyEnchanted = (item: Item): boolean =>
114	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
115	
116	const curseSurcharge = (item: Item): number =>
117	  isCursed(item) ? itemBasePremium(item) * CURSE_SURCHARGE_RATE : 0;
118	
119	const highEnchantmentSurcharge = (item: Item): number =>
120	  isHighlyEnchanted(item)
121	    ? itemBasePremium(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
122	    : 0;
123	
124	const itemSurchargeTotal = (items: Item[]): number =>
125	  items.reduce(
126	    (total, item) => total + curseSurcharge(item) + highEnchantmentSurcharge(item),
127	    0,
128	  );
129	
130	const loyaltyDiscount = (policyBase: number, customer: Customer): number =>
131	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS
132	    ? policyBase * LOYALTY_DISCOUNT_RATE
133	    : 0;
134	
135	const followUpContractDiscount = (policyBase: number, previousQuotes: number): number =>
136	  previousQuotes > 0 ? policyBase * FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0;
137	
138	const policyWideAdjustments = (
139	  policyBase: number,
140	  customer: Customer,
141	  previousQuotes: number,
142	): number =>
143	  firstInsuranceSurcharge(policyBase) -
144	  loyaltyDiscount(policyBase, customer) -
145	  followUpContractDiscount(policyBase, previousQuotes);
146	
147	const quote = (
148	  step: QuoteStep,
149	  customer: Customer,
150	  previousQuotes: number,
151	): QuoteResult => {
152	  const policyBase = policyBasePremium(step.items);
153	  const premiumBeforeRounding =
154	    policyBase +
155	    itemSurchargeTotal(step.items) +
156	    policyWideAdjustments(policyBase, customer, previousQuotes) +
157	    PROCESSING_FEE;
158	  return { premium: Math.ceil(premiumBeforeRounding) };
159	};
160	
161	interface Policy {
162	  items: Item[];
163	  remainingCap: number;
164	}
165	
166	const insuranceSum = (items: Item[]): number =>
167	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
168	
169	const payoutForDamage = (damage: Damage): number =>
170	  Math.max(0, damage.amount - DEDUCTIBLE_PER_DAMAGE);
171	
172	const claim = (step: ClaimStep, policy: Policy): ClaimResult => {
173	  const payout = step.incident.damages.reduce(
174	    (total, damage) => total + payoutForDamage(damage),
175	    0,
176	  );
177	  policy.remainingCap -= payout;
178	  return { payout: Math.floor(payout), remainingCap: policy.remainingCap };
179	};
180	
181	export const runScenario = (scenario: Scenario): ScenarioOutput => {
182	  const policies = new Map<number, Policy>();
183	  let quotesSoFar = 0;
184	
185	  const results = scenario.steps.map((step, index) => {
186	    if (step.op === "claim") {
187	      return claim(step, policies.get(step.policy)!);
188	    }
189	    const result = quote(step, scenario.customer, quotesSoFar);
190	    quotesSoFar += 1;
191	    policies.set(index, {
192	      items: step.items,
193	      remainingCap: insuranceSum(step.items) * CAP_MULTIPLIER,
194	    });
195	    return result;
196	  });
197	
198	  return { results };
199	};
