172	const claim = (step: ClaimStep, policy: Policy): ClaimResult => {
173	  const payout = step.incident.damages.reduce(
174	    (total, damage) => total + payoutForDamage(damage),
175	    0,
176	  );
177	  policy.remainingCap -= payout;
178	  return { payout: Math.floor(payout), remainingCap: policy.remainingCap };
179	};
180	
181	const policyFor = (items: Item[]): Policy => ({
182	  items,
183	  remainingCap: insuranceSum(items) * CAP_MULTIPLIER,
184	});
185	
186	const countQuotesBefore = (steps: Step[], stepIndex: number): number =>
187	  steps.slice(0, stepIndex).filter((step) => step.op === "quote").length;
188	
189	export const runScenario = (scenario: Scenario): ScenarioOutput => {
190	  // A policy is registered under the index of the step that quoted it; that
191	  // step index is the id later claim steps refer to. Claims mutate their
192	  // policy's remainingCap, so the register carries state across steps.
193	  const policies = new Map<number, Policy>();
194	
195	  const results = scenario.steps.map((step, stepIndex): StepResult => {
196	    if (step.op === "claim") {
197	      return claim(step, policies.get(step.policy)!);
198	    }
199	    policies.set(stepIndex, policyFor(step.items));
200	    return quote(
201	      step,
202	      scenario.customer,
203	      countQuotesBefore(scenario.steps, stepIndex),
204	    );
205	  });
206	
207	  return { results };
208	};
